def _apply_cross_die_net_weights(placedb, assignment: Mapping[int, str], multiplier: float) -> Tuple[int, float]:
    cross_die_ids = []
    for net_id in range(len(placedb.net2pin_map)):
        dies = set(_iter_node_dies_for_net(placedb, net_id, assignment))
        if len(dies) >= 2:
            cross_die_ids.append(net_id)
    automatic_weight = float(multiplier) == 1.0
    total_net_count = len(placedb.net2pin_map)
    if automatic_weight and total_net_count:
        automatic_weight = len(cross_die_ids) <= 0.12 * total_net_count
    for net_id in cross_die_ids:
        factor = float(multiplier)
        if automatic_weight:
            degree = len(placedb.net2pin_map[net_id])
            if degree <= 2:
                factor = 1.30
            elif degree == 3:
                factor = 1.15
            else:
                factor = 1.05
        if factor != 1.0:
            placedb.net_weights[net_id] *= factor
    return len(cross_die_ids), float(np.sum(placedb.net_weights))

